<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';
import {useProjectStore} from '../stores/project';
import {emptyValue,schemas,kindSchemas} from '../lib/validation';
import type {ContentObject,ContentDraft} from '@loreviva/sdk-ts';
import StageCanvas from '../components/StageCanvas.vue';
import PropertyPanel from '../components/PropertyPanel.vue';
import FieldErrors from '../components/FieldErrors.vue';
import DraftDiff from '../components/DraftDiff.vue';
import SchemaField from '../components/SchemaField.vue';
import ImpactCommands from '../components/ImpactCommands.vue';
import AssistantActions from '../components/AssistantActions.vue';
import PublishChecklist from '../components/PublishChecklist.vue';
const s=useProjectStore();const latest=ref<ContentDraft>();const compareError=ref<unknown>();const addKind=ref('SCENE');const notice=ref('');
// Retry the pending create or save through the project store, preserving its original request. Reading a comparison does not replace local input; accepting that server draft is an explicit UI action.
async function save(retry=false){try{const applied=retry?(s.pendingCreate?await s.createDraft(true):await s.saveDraft(true)):(s.basis?await s.saveDraft():await s.createDraft());notice.value=applied?(s.dirty?'请求中的版本已保存；仍有较新的本地修改。尚未发布。':'草稿已保存。尚未发布。'):(retry?'原保存已核验；当前草稿未改变。':'')}catch{notice.value=''}}
async function compare(){try{if(!s.basis)return;latest.value=await s.client.call('getContentDraft',{path:{draft_id:s.basis.draft_id},query:{product_id:s.productId}});compareError.value=undefined}catch(e){compareError.value=e}}
function add(){if(!s.editable)return;const object=emptyValue(schemas[kindSchemas[addKind.value]]) as ContentObject;Object.assign(object,{object_id:crypto.randomUUID(),version:'1',name:'未命名'+addKind.value,kind:addKind.value});s.editable.objects.push(object);s.selectedId=object.object_id}
function focusField(event:Event){const path=(event as CustomEvent<unknown>).detail;if(typeof path!=='string')return;const match=/^\/objects\/(\d+)(?:\/|$)/.exec(path);const object=match&&s.editable?.objects[Number(match[1])];if(object)s.selectedId=object.object_id}
onMounted(()=>window.addEventListener('studio-field-focus',focusField));onBeforeUnmount(()=>window.removeEventListener('studio-field-focus',focusField));
onBeforeRouteLeave(()=>!s.dirty||window.confirm('离开编辑页会保留本地修改，但尚未保存到服务器，继续吗？'));
</script>
<template><div class="page-heading"><div><p class="eyebrow">设定 · 关系 · 表现</p><h1>{{s.editable?.name||'世界编辑'}}</h1><p>先定义，再试演。每次保存都留下独立修订。</p></div><div v-if="s.editable" class="actions"><button :disabled="!s.dirty||s.busy||s.impactBlocked" @click="s.discardUnsaved();notice=''">取消修改</button><button class="primary" :disabled="!s.dirty||s.busy||s.impactBlocked" @click="save()">保存草稿</button></div></div><FieldErrors :error="s.error"/><FieldErrors :error="compareError"/><button v-if="s.error&&s.basis" @click="compare">读取服务器当前修订作比较（保留本地）</button><section v-if="latest&&s.editable" class="panel"><h2>当前服务器修订 {{latest.draft_revision}}</h2><DraftDiff :before="latest.input" :after="s.editable"/><button @click="s.acceptDraft(latest);latest=undefined">放弃本地修改并采用服务器当前内容</button></section><p v-if="notice" role="status" class="success">{{notice}}</p><button v-if="s.pendingSave||s.pendingCreate" class="quiet" @click="save(true)">用原请求键恢复保存</button><ImpactCommands/><template v-if="s.editable"><section class="panel draft-summary"><label>内容名称<input v-model="s.editable.name"></label><label>内容简介<textarea v-model="s.editable.description" rows="2"/></label><span class="badge">{{s.basis?'修订 '+s.basis.draft_revision:'尚未保存'}}</span></section><div class="editor-grid"><aside class="panel object-tree"><h2>对象</h2><button v-for="object in s.editable.objects" :key="object.object_id" :class="{active:object.object_id===s.selectedId}" @click="s.selectedId=object.object_id"><small>{{object.kind}}</small>{{object.name}}</button><label>新增类型<select v-model="addKind"><option v-for="kind in Object.keys(kindSchemas)" :key="kind">{{kind}}</option></select></label><button @click="add">添加对象</button></aside><StageCanvas :draft="s.editable" :selected-id="s.selectedId" @select="s.selectedId=$event" @move="(id,x,y)=>{s.selectedId=id;s.moveSelected(x,y)}"/><PropertyPanel/></div><details class="panel"><summary>模块岗位与 Skill 绑定</summary><p>绑定使用当前对象与固定引用。模型参数仅在模型设置内；Skill 标签仅作分类。</p><SchemaField field="module_agent_bindings" path="/module_agent_bindings" :schema="schemas.DraftInput.properties!.module_agent_bindings" :model-value="s.editable.module_agent_bindings" :objects="s.editable.objects" @update:model-value="s.editable!.module_agent_bindings=$event as typeof s.editable.module_agent_bindings"/><SchemaField field="skill_bindings" path="/skill_bindings" :schema="schemas.DraftInput.properties!.skill_bindings" :model-value="s.editable.skill_bindings" :objects="s.editable.objects" @update:model-value="s.editable!.skill_bindings=$event as typeof s.editable.skill_bindings"/></details><AssistantActions v-if="s.basis"/><PublishChecklist v-if="s.basis"/><DraftDiff v-if="s.basis&&s.dirty" :before="s.basis.input" :after="s.editable"/></template><p v-else class="empty">请先从工作空间打开或创建草稿。</p></template>
